return {
  [ [[v5748eaic9o9f]] ] = { t = [[圣武士与腐尸症]], q = [=[如果我免疫疾病，我是否免疫同时属于诅咒和疾病的[[腐尸症]]？]=], a = [[是。]], book = [[核心规则书]], date = [[2011/01/07]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fm#v5748eaic9o9f]], cat = [[FAQ]], ai = false, pages = { [[圣武士]] } },
  [ [[v5748eaic9p08]] ] = { t = [[圣疗与正能量]], q = [[圣武士的【圣疗】使用的是正能量吗？]], a = [[是。]], book = [[核心规则书]], date = [[2012/01/02]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fm#v5748eaic9p08]], cat = [[FAQ]], ai = false, pages = { [[圣武士]] } },
  [ [[v5748eaic9qv0]] ] = { t = [[制裁邪恶与虚体]], q = [=[【制裁邪恶】能够绕过[[虚体(怪物能力)|虚体]]特殊品质的防御吗？]=], a = [[制裁邪恶并非武器上的效果，而是圣武士本人身上的效果。武器依然需要是魔法武器才能伤害虚体生物，而即便是魔法武器，也只能对其造成半数伤害。]], book = [[核心规则书]], date = [[2013/01/07]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fm#v5748eaic9qv0]], cat = [[FAQ]], ai = false, pages = { [[圣武士]] } },
  [ [[v5748eaic9qwv]] ] = { t = [[圣武士神契与双武器]], q = [[圣武士的【神契】：我能消耗两次该能力的每日次数，来强化两件武器、或一件双头武器的两端吗？]], a = [[可以。]], book = [[核心规则书]], date = [[2013/01/08]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fm#v5748eaic9qwv]], cat = [[FAQ]], ai = false, pages = { [[圣武士]] } },
  [ [[v5748eaic9u46]] ] = { t = [[圣武士的侦测邪恶]], q = [[圣武士需要先花一个标准动作启动【侦测邪恶】，再花一个移动动作专注于单个生物或物品吗？]], a = [[不需要。第一句话与该能力的其余部分是相互独立的，它提供的是使用侦测邪恶的另一种选择。圣武士可以用移动动作专注于单个生物或物品，以代替用标准动作启动普通的侦测邪恶。]], book = [[核心规则书]], date = [[2015/01/11]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fm#v5748eaic9u46]], cat = [[FAQ]], ai = true, pages = { [[圣武士]] } },
  [ [[v5748eaic9vk5]] ] = { t = [[察觉的搜索范围]], q = [=[当我以移动动作使用察觉技能搜索陷阱或其他秘密时，能搜索多大的区域？核心规则书没有说明，《掉链子》提到10尺×10尺的区域，但那属于可选的[[整合技能]]子系统。]=], a = [=[按照《极限诡道》，察觉检定在游戏中以两种方式发生。第一种是自动的、反应式的。某些刺激会自动要求进行察觉检定，例如有生物使用隐匿（这会要求进行一次对抗的察觉检定），或是远处传来战斗或交谈的声响。另一种则是玩家主动要求进行察觉检定，因为她的PC正有意地搜索某样东西（这就是用来发现陷阱的那种察觉；但如果你拥有盗贼天赋[[陷阱嗅觉]]，则变为反应式）。这至少需要一个移动动作，但往往要花费长得多的时间。

核心规则没有规定PC能主动搜索多大的区域，但单次察觉检定所覆盖的区域不应大于10尺×10尺，如果该区域杂乱，往往还应更小。例如，在以阴谋为主的游戏中，翻查塞满文件的文件柜是很常见的事。柜子本身可能只占5尺×5尺的区域，但其中文件的数量可能使一次搜索格外耗时。

不过，这并不意味着GM或玩家必须对每个10尺×10尺的区域各掷一次察觉检定。更顺畅的做法是，由GM为每名搜索中的角色秘密掷几次察觉检定，然后只在PC搜索的区域里确实有东西可找时，才采用对应的那一次结果。]=], book = [[核心规则书]], date = [[2017/01/03]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fm#v5748eaic9vk5]], cat = [[FAQ]], ai = true, pages = { [[察觉]] } },
  [ [[v5748eaic9ouz]] ] = { t = [[制作的物品与基于等级的财富]], q = [[如果PC拥有物品制造专长，他制造出的物品算作它的价格还是成本？]], a = [[算作该物品的成本，而非价格。这会在两方面用到。

如果你在为较高等级的PC配备装备，就必须按成本计算制造出的物品。否则该角色根本无法从拥有这个专长中获得任何好处。当然，GM可以自由地为配备装备设限，例如“用于防具的财富不得超过40%”（而不是第400页所述的“均衡做法”，即PC在防具上的花费不应超过25%）。

如果你在审视队伍整体的基于等级的财富，也必须按成本计算制造出的物品。否则，若按价格计算，制造者看起来就会拥有超出其等级应有水平的财富，GM就不得不通过削减该角色之后获得的财宝，使其更接近目标装备价值。这最终意味着该角色的装备价值与不会制造物品的角色相同——实际上完全抵消了拥有这个专长的任何优势。]], book = [[核心规则书]], date = [[2012/01/01]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fm#v5748eaic9ouz]], cat = [[FAQ]], ai = false, pages = { [[游戏掌控]] } },
  [ [[v5748eaic9qnt]] ] = { t = [[近距射击与溅射伤害]], q = [[我能把这个专长的额外伤害加到溅射武器的溅射伤害上吗？]], a = [[不能，近距射击的额外伤害只适用于溅射武器直接命中的目标（包括炼金术师炸弹的直接命中）。]], book = [[核心规则书]], date = [[2013/01/05]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fm#v5748eaic9qnt]], cat = [[FAQ]], ai = false, pages = { [[近距射击]] } },
  [ [[v5748eaic9nvx]] ] = { t = [[毒素的叠加与豁免]], q = [[毒素之间是如何相互叠加的？何时、如何进行豁免？如果目标置身于超过1剂以上的毒素中，如何确定豁免DC？]], a = [[每当角色遭到毒素侵染时（譬如被使用毒素的攻击命中），就有一次针对该毒素的豁免机会。该毒素的豁免DC如毒素描述中所列，但目标身上当前每有1剂该毒素在起作用，豁免DC就+2（不计入此刻正要通过豁免来对抗的那1剂新毒素）。已痊愈或已失效的毒素不计入。此外，中毒的生物在自己的回合内必须进行1次针对毒素的豁免，但这次豁免可以在该生物回合内的任意时点进行。它无法通过准备动作或延迟动作来推迟。有关毒素及其叠加的更多信息，请参阅关于毒素的FAQ博客文章。]], book = [[核心规则书]], date = [[2011/01/03]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fm#v5748eaic9nvx]], cat = [[FAQ]], ai = false, pages = { [[特殊能力]] } },
  [ [[v5748eaic9p1l]] ] = { t = [[药水与豁免]], q = [[如果我喝下一瓶药水，是否自动放弃了对该药水效果的豁免？]], a = [[不会。药水的规则中没有任何内容改变你对药水里所存法术是否有豁免检定。即便有人递给你一瓶毒药药水、并告诉你那是治疗重伤药水，你依然有权进行豁免。]], book = [[核心规则书]], date = [[2012/01/03]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fm#v5748eaic9p1l]], cat = [[FAQ]], ai = false, pages = { [[魔法物品/药水]] } },
  [ [[v5748eaic9qno]] ] = { t = [[猛力攻击与单手持双手武器]], q = [[如果我用单手持握一件双手武器（如骑乘中持用长枪），我还能获得使用双手武器时猛力攻击的+50%伤害吗？]], a = [[可以。]], book = [[核心规则书]], date = [[2013/01/05]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fm#v5748eaic9qno]], cat = [[FAQ]], ai = false, pages = { [[猛力攻击]] } },
  [ [[v5748eaic9quw]] ] = { t = [[单手持用双手武器的力量与猛力攻击]], q = [[当某个专长或其他特殊能力说要把通常需要双手持用的武器当作单手武器时，在决定如何应用力量调整值或猛力攻击专长时，它视为单手武器还是双手武器？]], a = [[如果你是用单手持用它（即便它通常是双手武器），那么在决定应用多少力量、猛力攻击的伤害加值等方面，都将它视为单手武器。]], book = [[核心规则书]], date = [[2013/01/07]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fm#v5748eaic9quw]], cat = [[FAQ]], ai = false, pages = { [[猛力攻击]] } },
  [ [[v5748eaic9qwu]] ] = { t = [[在空法术位中准备法术]], q = [[《魔法》一章说，法师可以空出法术位，之后再来准备其中的法术。其他职业也能这样做吗？]], a = [=[该文字写成时，法师是唯一准备奥术法术的职业。这一选项同样适用于[[魔战士]]和[[女巫]]（这两个也都是准备奥术法术的职业）。]=], book = [[核心规则书]], date = [[2013/01/08]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fm#v5748eaic9qwu]], cat = [[FAQ]], ai = true, pages = { [[魔法]] } },
  [ [[v5748eaic9nib]] ] = { t = [[进阶职业与法术书]], q = [[法师（或其他使用法术书的角色）在获得一个提升施法能力的进阶职业的等级时，能得到额外的法术加入法术书吗？]], a = [[不能。施法等级的提升除了每日法术数、已知法术（对自发施法者而言）和总体施法者等级的提高之外，不带来任何其他好处。他必须花费时间和金钱，才能把新法术加入自己的法术书。]], book = [[核心规则书]], date = [[2010/01/11]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fm#v5748eaic9nib]], cat = [[FAQ]], ai = true, pages = { [[进阶职业]], [[魔法]] } },
  [ [[v5748eaic9r95]] ] = { t = [[进阶职业的先决条件]], q = [[如果某个进阶职业要求某项技能5级，而我在该技能上有6级，我仍然满足要求吗？]], a = [=[是的，因为技能等级是向下兼容的：若你某项技能有6级，那么你在该技能上也有5级，因此满足“该技能5级”的要求。

同理，若你的BAB为+6，那么你的BAB也为+5，因此满足“BAB+5”的要求。

同理，若你力量15，那么你也有力量13，因此满足猛力攻击的“力量13”专长先决条件。

专长先决条件则不是向下兼容的，因为生物有可能在并未满足某专长先决条件的情况下拥有该专长。例如，[[游侠]]可以选择[[精准射击]]作为游侠奖励专长，而无需拥有[[近距射击]]专长；他并不满足[[远程射击]]的先决条件（其先决条件是近距射击），因为他实际上并没有近距射击专长，尽管他有一个以近距射击为先决条件的专长。]=], book = [[核心规则书]], date = [[2015/01/02]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fm#v5748eaic9r95]], cat = [[FAQ]], ai = false, pages = { [[进阶职业]] } },
  [ [[v5748eaic9o2p]] ] = { t = [[防护邪恶与魅惑、胁迫效果]], q = [=[防护邪恶对所有魅惑和胁迫效果都有效吗？还是只对施法者能够控制目标的魅惑和胁迫效果有效，例如[[魅惑人类]]、[[命令术]]和[[支配人类]]（因此不包括[[睡眠术]]或[[困惑术]]这类效果，因为施法者对目标并没有持续的影响力或傀儡般的控制）？]=], a = [[后一种理解是正确的：防护邪恶只对施法者能够控制目标的魅惑和胁迫效果有效，例如命令术、魅惑人类和支配人类；对睡眠术或困惑术无效。（睡眠是这个问题上的边界情形，但设计者认为，“这个法术压倒了你大脑的睡眠中枢”与“这个法术压倒了你对他人命令的抵抗”差别足够大。）]], book = [[核心规则书]], date = [[2011/01/05]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fm#v5748eaic9o2p]], cat = [[FAQ]], ai = true, pages = { [[防护邪恶]] } },
  [ [[v5748eaic9qd2]] ] = { t = [[防护邪恶与非邪恶的控制]], q = [[防护邪恶的“防护被占据和精神控制”这一效果，对非邪恶的控制类法术和效果也有效吗？]], a = [[不。法术写明：“第二种效果只对邪恶生物或物体创造的法术或效果起作用。”因此，如果一个混乱中立的敌人对你施放魅惑人类，防护邪恶不会有任何作用，因为法术和施法者都不是邪恶的。]], book = [[核心规则书]], date = [[2013/01/03]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fm#v5748eaic9qd2]], cat = [[FAQ]], ai = true, pages = { [[防护邪恶]] } },
  [ [[v5748eaic9o63]] ] = { t = [[法术瞬发与长施法时间]], q = [=[我能在施法时间为“1轮”的法术上（譬如[[变巨术]]）使用法术瞬发吗？在施法时间为“1个整轮动作”（譬如自发施法者对法术使用超魔专长）的法术上呢？]=], a = [=[皆可。两者的施法时间都没有超过法术瞬发“比1个整轮动作更长”的限制，因此都能被瞬发。

这意味着一名术士可以用迅捷动作施展“强效瞬发[[魔法飞弹]]”。同样地，由于多个超魔专长并不会让施法时间变得比1个整轮动作更长，术士也能用迅捷动作施展“强效默发静发瞬发魔法飞弹”。]=], book = [[核心规则书]], date = [[2011/01/06]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fm#v5748eaic9o63]], cat = [[FAQ]], ai = false, pages = { [[法术瞬发]] } },
  [ [[v5748eaic9qnr]] ] = { t = [[接触法术与手套类武器]], q = [=[戴着[[铁手套]]、[[拳套]]或类似手套状的武器，对于意外释放持有的接触法术而言，算作“碰触了任何东西”吗？]=], a = [[不算。]], book = [[核心规则书]], date = [[2013/01/05]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fm#v5748eaic9qnr]], cat = [[FAQ]], ai = true, pages = { [[魔法]] } },
  [ [[v5748eaic9r42]] ] = { t = [[多次接触的接触法术]], q = [[如果某个法术允许多次接触，在这些次数全部用完之前，是否都视为你一直在维持法术能量？]], a = [[是。]], book = [[核心规则书]], date = [[2013/01/09]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fm#v5748eaic9r42]], cat = [[FAQ]], ai = true, pages = { [[魔法]] } },
  [ [[v5748eaic9ve2]] ] = { t = [[对敌人发动接触攻击]], q = [[《魔法》和《战斗》两章说，我可以用一个标准动作接触一名盟友，或用一个整轮动作接触至多六名盟友，并且可以把传递接触法术与天生攻击或徒手打击结合起来。但如果我只想把接触法术传递给一名敌人呢？书里只说我可以“一轮接一轮”地这样做。]], a = [[除了作为施法一部分的那次免费动作之外，通过接触对敌人发动接触攻击是一个标准动作。它不能与全力攻击一同使用。]], book = [[核心规则书]], date = [[2017/01/02]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fm#v5748eaic9ve2]], cat = [[FAQ]], ai = true, pages = { [[魔法]] } },
  [ [[v5748eaic9o4q]] ] = { t = [[准备冲锋]], q = [[我能准备一个冲锋动作吗？]], a = [[不能。冲锋的规则写明，只有当你“在回合内受限只能进行一个标准动作”时，才能把冲锋作为一个标准动作进行。虽然准备动作的文字说你可以准备一个标准动作，但这并不满足冲锋动作文字中的要求。（见核心规则书第198页和第203页。）]], book = [[核心规则书]], date = [[2011/01/06]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fm#v5748eaic9o4q]], cat = [[FAQ]], ai = true, pages = { [[特殊先攻动作]] } },
  [ [[v5748eaic9qif]] ] = { t = [[整夜不睡]], q = [[如果角色整夜不睡，将会遭受怎样的不利？]], a = [=[角色将陷入[[疲乏]]。]=], book = [[核心规则书]], date = [[2013/01/04]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fm#v5748eaic9qif]], cat = [[FAQ]], ai = false, pages = { [[休整期活动]] } },
  [ [[v5748eaic9qnu]] ] = { t = [[法术反制戒指与范围法术]], q = [=[法术反制戒指：它能反制[[火球术]]之类的范围法术吗？]=], a = [=[戒指只影响以你为目标的法术，而不影响范围包括了你的法术。一种可能的理解是，戒指会使你免疫该次施法（而区域内的其他部分照常受到影响），但那需要额外的说明文字，并会造成奇怪的局面：你会免疫[[操纵水位]]或[[铜墙铁壁]]，并能在这类效果中自由穿行。因此，更清晰的裁定方式是：戒指只影响以你为目标的法术。

（该魔法物品的措辞可能会在未来的勘误中得到澄清。）]=], book = [[核心规则书]], date = [[2013/01/05]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fm#v5748eaic9qnu]], cat = [[FAQ]], ai = false, pages = { [[法术反制戒指]] } },
  [ [[v5748eaic9ofl]] ] = { t = [[超魔权杖与类法术能力]], q = [[我能用超魔权杖来改变类法术能力吗？]], a = [[不能。超魔权杖让你能把超魔专长应用到法术上，而超魔专长对类法术能力不起作用。]], book = [[核心规则书]], date = [[2011/01/08]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fm#v5748eaic9ofl]], cat = [[FAQ]], ai = false, pages = { [[魔法物品/权杖]] } },
  [ [[v5748eaic9og5]] ] = { t = [[卷轴与施法者等级检定失败]], q = [[如果我启动卷轴时施法者等级检定失败，但没有发生事故，卷轴会被用掉吗？]], a = [[不会。

更新：第490页——在“启动”一节中，要点之后的第一段里，加入以下句子：“若施法者等级检定失败但没有发生事故，卷轴不会被消耗。”]], book = [[核心规则书]], date = [[2011/01/08]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fm#v5748eaic9og5]], cat = [[FAQ]], ai = true, pages = { [[魔法物品/卷轴]] } },
  [ [[v5748eaic9o84]] ] = { t = [[选择导能与看见目标]], q = [[我必须要能看见一个生物，才能把它排除在我引导的能量的影响之外吗？]], a = [=[和以生物为目标的法术一样，你必须能够看到或碰触到一个生物，才能对其造成影响（在本专长中，则是选择让其不受影响）。仅仅是定位出隐形生物所在的方格还不够——你必须能够看到或碰触到该生物。

注意这和炼金术师的【精准炸弹】[[科研发现]]的运作方式不同，后者允许炼金术师把方格（而非目标）排除在炸弹的溅射范围之外。]=], book = [[核心规则书]], date = [[2011/01/07]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fm#v5748eaic9o84]], cat = [[FAQ]], ai = false, pages = { [[选择导能]] } },
  [ [[v5748eaic9vdp]] ] = { t = [[盾牌大师忽略的减值]], q = [=[盾牌大师写着“你在持用另一把武器时，使用盾牌的攻击检定不会承受任何减值”，从上下文看似乎指的是不承受[[双武器格斗]]的减值，但它只说了“任何减值”，所以并不明确。这个专长到底让角色无视哪些减值？]=], a = [[盾牌大师让角色在持用另一把武器时，无视用盾牌进行攻击检定所承受的双武器格斗减值，但不无视任何其他减值。]], book = [[核心规则书]], date = [[2017/01/02]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fm#v5748eaic9vdp]], cat = [[FAQ]], ai = true, pages = { [[盾牌大师]] } },
  [ [[v5748eaic9qm0]] ] = { t = [[电爪与非接触攻击传递]], q = [[如果我不是以接触攻击，而是以别的方式（比如天生武器）传递这个法术，攻击检定上还能得到+3吗？]], a = [[能。+3加值并不取决于是否以近战接触攻击来传递电击。例如，魔战士用法术打击通过武器传递电爪，攻击检定也会得到+3加值。]], book = [[核心规则书]], date = [[2013/01/05]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fm#v5748eaic9qm0]], cat = [[FAQ]], ai = true, pages = { [[电爪]] } },
  [ [[v5748eaic9tga]] ] = { t = [[更换关键属性与检定]], q = [=[如果我改变了某项技能（或其他检定）的关键属性，例如把[[知识]]的关键属性从智力改为魅力，它就不再是基于智力的检定了吗？它现在是基于魅力的检定吗？]=], a = [=[通常是的——在掷检定的当下，如果你替换了所用的属性，该检定就基于新的属性。以上例而言，在掷骰时，知识对你来说就是基于魅力、而非基于智力的技能，这会影响那些给予“基于其关键属性的检定”加值的专长、法术或物品（如[[劝诱头饰]]）。

然而，如果你是在检定上追加第二个属性调整值，则并非如此。例如，在先攻检定上同时加上感知和敏捷调整值时，先攻仍然是敏捷检定，而不是感知检定。

此外，这只会在掷骰的当下改变该检定，因此不会改变静态的职业特性，或角色构建时做出的选择，例如你的职业的本职技能。例如，那些以“所有基于智力的技能”作为本职技能的职业，是糟糕措辞的受害者；而且有时某些效果只在部分场合而非全部场合改变属性依赖，使情形更加混乱，这就是为什么只针对某一次特定的掷骰来检查新的依赖。]=], book = [[核心规则书]], date = [[2015/01/06]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fm#v5748eaic9tga]], cat = [[FAQ]], ai = true, pages = { [[技能]] } },
}